def _determine_violation(account_id, usage_tier, expected_plan, assigned_plan,
                         expected_price, assigned_price, approvals_df, contracts_df,
                         legacy_plan, seats, migration_date):
    if assigned_plan == expected_plan and abs(assigned_price - expected_price) < 0.01:
        return "no_violation"

    # 1. Check if assigned plan does not match expected plan
    if assigned_plan != expected_plan:
        # Check if it matches an expired/invalid exception
        if approvals_df is not None and not approvals_df.empty:
            acct_approvals = approvals_df[
                (approvals_df["account_id"] == account_id) &
                (approvals_df["exception_type"] == "plan_override")
            ]
            for _, row in acct_approvals.iterrows():
                status = str(row.get("approval_status", "")).strip().lower()
                expiry = row.get("expiry_date")
                approved_plan = str(row.get("approved_plan", "")).strip()
                if approved_plan == assigned_plan:
                    is_expired = False
                    if status == "expired":
                        is_expired = True
                    elif pd.notna(expiry):
                        try:
                            if pd.Timestamp(expiry) < pd.Timestamp(migration_date):
                                is_expired = True
                        except Exception:
                            pass
                    if is_expired:
                        return "expired_exception"

        # Check if it is usage_tier_miscalculated
        other_tiers = [t for t in ["Low", "Medium", "High"] if t != usage_tier]
        is_wrong_tier = False
        for ot in other_tiers:
            mapped_plan = PLAN_MAPPING.get((legacy_plan, ot))
            if mapped_plan == assigned_plan:
                is_wrong_tier = True
                break
        if is_wrong_tier:
            return "usage_tier_miscalculated"

        return "wrong_plan"

    # 2. Plan is correct, but price is wrong
    # Check missing grandfathering first
    if contracts_df is not None and not contracts_df.empty:
        contract = contracts_df[contracts_df["account_id"] == account_id]
        if not contract.empty:
            row = contract.iloc[0]
            gf_until = row.get("grandfathered_until")
            if gf_until and not pd.isna(gf_until):
                try:
                    gf_dt = pd.Timestamp(gf_until)
                    migration_dt = pd.Timestamp(migration_date)
                    if gf_dt >= migration_dt:
                        un_gf_floor = SEAT_FLOORS.get(expected_plan, 0.0)
                        un_gf_price = round(max(BASE_PRICES.get(expected_plan, 0.0), seats * un_gf_floor), 2)
                        if abs(assigned_price - un_gf_price) < 0.01:
                            return "missing_grandfathering"
                except Exception:
                    pass

    # Check if mismatch is explained by an expired exception
    if approvals_df is not None and not approvals_df.empty:
        acct_approvals = approvals_df[
            (approvals_df["account_id"] == account_id) &
            (approvals_df["exception_type"] == "price_override")
        ]
        for _, row in acct_approvals.iterrows():
            status = str(row.get("approval_status", "")).strip().lower()
            expiry = row.get("expiry_date")
            app_price = row.get("approved_price")
            if pd.notna(app_price):
                try:
                    app_price_val = float(app_price)
                    if abs(assigned_price - app_price_val) < 0.01:
                        is_expired = False
                        if status == "expired":
                            is_expired = True
                        elif pd.notna(expiry):
                            if pd.Timestamp(expiry) < pd.Timestamp(migration_date):
                                is_expired = True
                        if is_expired:
                            return "expired_exception"
                except Exception:
                    pass

    return "wrong_price_floor"

def load_exception_approvals(data_dir):
    path = os.path.join(data_dir, "exception_approvals.xlsx")
    xl = pd.ExcelFile(path)
    approvals_df = xl.parse("Approvals", header=5)
    approvals_df.columns = [c.strip() for c in approvals_df.columns]
    # Rename exception_type column or standard mappings
    approvals_df = approvals_df.rename(columns={"approval_type": "exception_type"})
    ref_r4 = xl.parse("Ref_R4")
    ref_r4_dict = dict(zip(ref_r4["k"].astype(str), ref_r4["v"]))
    ref_m3 = xl.parse("Ref_M3")
    ref_m3_dict = dict(zip(ref_m3["b"].astype(str), ref_m3["rk"].astype(str)))
    ref_x7 = xl.parse("Ref_X7")
    ref_x7_dict = dict(zip(ref_x7["approval_id"].astype(str), ref_x7["tgt_plan"].astype(str)))
    for idx, row in approvals_df.iterrows():
        app_id = str(row["approval_id"])
        b_key = str(row["b_key"]) if pd.notna(row["b_key"]) else None
        if pd.isna(row["approved_plan"]) or str(row["approved_plan"]).strip() == "" or str(row["approved_plan"]) == "nan":
            if app_id in ref_x7_dict:
                approvals_df.at[idx, "approved_plan"] = ref_x7_dict[app_id]
        if pd.isna(row["approved_price"]) or str(row["approved_price"]).strip() == "" or str(row["approved_price"]) == "nan":
            if b_key in ref_m3_dict:
                rk = ref_m3_dict[b_key]
                if rk in ref_r4_dict:
                    approvals_df.at[idx, "approved_price"] = float(ref_r4_dict[rk])
    return approvals_df

# Run simulation
data_dir = "/root/data"
migration_date = "2026-04-01"
accounts_df = pd.read_csv(os.path.join(data_dir, "legacy_accounts.csv"))
events_df = pd.read_csv(os.path.join(data_dir, "product_usage_events.csv"), parse_dates=["event_date"])
contracts = {}
with open(os.path.join(data_dir, "contract_terms.jsonl")) as f:
    for line in f:
        rec = json.loads(line.strip())
        contracts[rec["account_id"]] = rec
contracts_df = pd.DataFrame(contracts.values())
approvals_df = load_exception_approvals(data_dir)
assignments_df = pd.read_csv(os.path.join(data_dir, "new_plan_assignments.csv"))

audit_rows = []
for _, acct in accounts_df.iterrows():
    account_id = acct["account_id"]
    legacy_plan = acct["legacy_plan"]
    seats = int(acct["current_seats"])
    contract_row = contracts.get(account_id)

    usage_tier, expected_plan = determine_expected_plan(
        account_id, legacy_plan, events_df, approvals_df,
        contracts_df=contracts_df,
        migration_effective_date=migration_date
    )

    computed_price = calculate_expected_price(
        expected_plan, seats, contract_row, migration_date
    )
    expected_price = apply_price_exception(
        account_id, computed_price, approvals_df, migration_date
    )

    assignment = assignments_df[assignments_df["account_id"] == account_id]
    assigned_plan = assignment["assigned_new_plan"].values[0]
    assigned_price = float(assignment["assigned_monthly_price"].values[0])

    violation_type = _determine_violation(
        account_id, usage_tier, expected_plan, assigned_plan,
        expected_price, assigned_price, approvals_df, contracts_df,
        legacy_plan, seats, migration_date
    )

    migration_status = "pass" if violation_type == "no_violation" else "fail"
    revenue_impact = round(assigned_price - expected_price, 2)

    audit_rows.append({
        "account_id": account_id,
        "legacy_plan": legacy_plan,
        "usage_tier": usage_tier,
        "expected_new_plan": expected_plan,
        "assigned_new_plan": assigned_plan,
        "expected_monthly_price": expected_price,
        "assigned_monthly_price": assigned_price,
        "migration_status": migration_status,
        "violation_type": violation_type,
        "revenue_impact_usd": revenue_impact,
    })

audit_df = pd.DataFrame(audit_rows)
print(audit_df.to_string())
